ciri_media_sosial.py<pre><code>"""Mengenali ciri teks media sosial dengan regex sederhana (ILUSTRATIF)."""
import re

POLA = {
    "url": re.compile(r"https?://\S+"),
    "mention": re.compile(r"@\w+"),
    "hashtag": re.compile(r"#\w+"),
    "emoji": re.compile("[\U0001F300-\U0001FAFF☀-➿]"),
    "huruf_berulang": re.compile(r"(\w)\1{2,}"),
}

CONTOH = "@bpbd_kota TOLOOONG banjir naik cepet bgt di Jl. Melati 🙏 #banjir https://t.co/xyz123"


def ekstrak_ciri(teks):
    return {nama: [m.group(0) for m in pola.finditer(teks)] for nama, pola in POLA.items()}


if __name__ == "__main__":
    print(CONTOH)
    for nama, hasil in ekstrak_ciri(CONTOH).items():
        print(f"{nama:15}: {hasil}")
</code></pre>

16_debugging_pengujian.py<pre><code>"""Fungsi kecil yang diuji dengan assert."""


def hitung_kata(teks):
    return len(teks.split())


def tes_hitung_kata():
    assert hitung_kata("banjir naik") == 2
    assert hitung_kata("") == 0
    assert hitung_kata("  banjir   naik  ") == 2


if __name__ == "__main__":
    tes_hitung_kata()
    print("semua tes lolos")
    try:
        assert hitung_kata("a b") == 3, "seharusnya 2 kata"
    except AssertionError as e:
        print("AssertionError:", e)
