09_exception_handling.py<pre><code>"""Exception handling."""


def ke_angka(teks):
    try:
        return int(teks)
    except ValueError:
        return None


print(ke_angka("12"), ke_angka("dua belas"))

try:
    {"a": 1}["b"]
except KeyError as e:
    print("KeyError:", e)
try:
    1 / 0
except ZeroDivisionError as e:
    print("ZeroDivisionError:", e)
finally:
    print("selesai")


def rata_panjang(daftar):
    if not daftar:
        raise ValueError("daftar teks tidak boleh kosong")
    return sum(len(t) for t in daftar) / len(daftar)


try:
    rata_panjang([])
except ValueError as e:
    print("ValueError:", e)
print(rata_panjang(["aa", "bbbb"]))
</code></pre>

07_function_parameter.py<pre><code>"""Function dan parameter."""


def hitung_kemunculan(teks, kata, huruf_kecil=True):
    """Mengembalikan berapa kali `kata` muncul pada teks."""
    if huruf_kecil:
        teks = teks.lower()
    return teks.split().count(kata)


print(hitung_kemunculan("Banjir banjir BANJIR naik", "banjir"))
print(hitung_kemunculan("Banjir banjir BANJIR naik", "banjir", huruf_kecil=False))


def ringkas(teks, *, maks=20):
    return teks if len(teks) &lt;= maks else teks[:maks] + "..."


print(ringkas("Banjir setinggi dada di Jl. Melati"))
print(ringkas("Banjir setinggi dada di Jl. Melati", maks=10))


def statistik(angka):
    return min(angka), max(angka), sum(angka) / len(angka)


kecil, besar, rata = statistik([3, 5, 4])
print(kecil, besar, rata)


def tambah(item, daftar=None):
    if daftar is None:
        daftar = []
    daftar.append(item)
    return daftar


print(tambah(1), tambah(2))
</code></pre>

